Read the three source sheets as 5-column row tuples, treating blank rows as absent. Form the multiset Existing + Additions, then remove each Retired row by exact normalized match. Write the resulting rows to Consolidated Tracker!A3:E11, clearing the region first.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

def normalize(v):
    if v is None:
        return None
    if isinstance(v, str):
        return v.strip()
    if isinstance(v, float) and v.is_integer():
        return int(v)
    return v

def read_rows(sheet_name, start_row=3):
    ws = vals[sheet_name]
    rows = []
    for r in range(start_row, ws.max_row + 1):
        row = tuple(normalize(ws.cell(row=r, column=c).value) for c in range(1, 6))
        if all(x is None or (isinstance(x, str) and x == "") for x in row):
            continue
        rows.append(row)
    return rows

existing = read_rows("Existing Task")
additions = read_rows("Additions")
retired = read_rows("Retired")

result = []
result.extend(existing)
result.extend(additions)

for row in retired:
    try:
        result.remove(row)
    except ValueError:
        pass

ws = wb["Consolidated Tracker"]

# Clear the answer region A3:E11
for r in range(3, 12):
    for c in range(1, 6):
        ws.cell(row=r, column=c).value = None

# Write up to 9 rows into A3:E11
for i, row in enumerate(result[:9]):
    for j, value in enumerate(row):
        ws.cell(row=3 + i, column=1 + j).value = value

wb.save(OUT)

print("existing:", len(existing), "additions:", len(additions), "retired:", len(retired), "result:", len(result))
print("first result rows:", result[:3])
